def top_ip(lines):
    counts = {}
    for line in lines:
        ip = line.split()[0]
        counts[ip] = counts.get(ip, 0) + 1
    return max(counts, key=counts.get)

alt:
from collections import Counter

def top_ip(lines):
    return Counter(l.split()[0] for l in lines).most_common(1)[0][0]
